function freeze(value) { if (!value || typeof value !== 'object' || Object.isFrozen(value)) return value; for (const child of Object.values(value)) freeze(child); return Object.freeze(value); }
export const CHARACTER_MODEL_ASSETS = freeze(DATA);
export const CHARACTER_MODEL_PIPELINE = CHARACTER_MODEL_ASSETS.pipeline;
export const CHARACTER_MODEL_ASSETS_BY_HERO_ID = Object.freeze(Object.fromEntries(CHARACTER_MODEL_ASSETS.heroes.map((entry) => [entry.heroId, entry])));
export function getCharacterModelAsset(heroId) { return CHARACTER_MODEL_ASSETS_BY_HERO_ID[String(heroId || '')] || null; }
export function isCharacterModelQualityAccepted(entry) { const ids = CHARACTER_MODEL_PIPELINE.qualityGateIds; return !!entry && entry.status === CHARACTER_MODEL_PIPELINE.runtimeStatus && entry.runtimeEligible === true && ids.every((id) => entry.quality?.gates?.[id] === true) && Array.isArray(entry.quality?.evidence) && entry.quality.evidence.length >= ids.length; }
export function getRuntimeEligibleCharacterModelAsset(heroId) { const entry = getCharacterModelAsset(heroId); return isCharacterModelQualityAccepted(entry) ? entry : null; }
